import { Breadcrumbs, PageHeader } from 'components';
import { TrainingCard } from 'pages/trainingHub/components';
import { Training, TrainingHubData } from 'pages/trainingHub/domain';
import { StyledGridContainer, StyledHomeHeaderContainer } from 'shared/Styles';

import { useTrainingData } from '../../hooks';
import {
  StyledTrainingHubHome,
  StyledTrainingHubWrapper,
} from '../Home/Home.styles';
import { StyledRecentlyAddedContainer } from './RecentlyAdded.styles';

export const RecentlyAdded = () => {
  const { trainingData } = useTrainingData();
  const pillars = Object.keys(trainingData);
  const trainings = pillars.map(
    (pillar) => trainingData[pillar as keyof TrainingHubData].trainings,
  );
  const flattenedTrainings = trainings.flat();
  const pageList = [
    { pageName: 'Training Hub', href: '/training-hub' },
    { pageName: 'Recently Added', href: '/training-hub/recently-added' },
  ];

  return (
    <StyledGridContainer>
      <StyledTrainingHubWrapper>
        <StyledTrainingHubHome>
          <Breadcrumbs pageList={pageList} showIcon={true} />
          <StyledHomeHeaderContainer>
            <PageHeader
              title="Recently Added"
              subtitle="Trainings that were added in the past 30 days."
            />
          </StyledHomeHeaderContainer>
        </StyledTrainingHubHome>
        <StyledRecentlyAddedContainer>
          {flattenedTrainings.map((training: Training) => (
            <TrainingCard key={training.id} training={training} />
          ))}
        </StyledRecentlyAddedContainer>
      </StyledTrainingHubWrapper>
    </StyledGridContainer>
  );
};
